def check_seq(m_seq, v=9):
    import math
    def solve_congruences(congs):
        n = 0
        m = 1
        for a, M in congs:
            g = math.gcd(m, M)
            if (a - n) % g != 0:
                return None
            m_inv = pow(m // g, -1, M // g)
            k = ((a - n) // g * m_inv) % (M // g)
            n = n + m * k
            m = (m * M) // g
        return n, m

    congs = [(2**m - i, 2**(m+1)) for i, m in enumerate(m_seq)]
    res = solve_congruences(congs)
    if res is None:
        return False

    n_sol, mod_sol = res
    if n_sol <= 0:
        n_sol += mod_sol

    u = n_sol - v
    if u <= 0:
        for k in range(1, 100):
            u = n_sol + k * mod_sol - v
            if u > 0:
                valid = True
                for i in range(v):
                    if (f(u+i+v) - f(u+i)) % 4 != 0:
                        valid = False
                        break
                if valid:
                    return True
        return False
    else:
        valid = True
        for i in range(v):
            if (f(u+i+v) - f(u+i)) % 4 != 0:
                valid = False
                break
        return valid

